import { booths } from "../data/booths";
import BoothCard from "../components/BoothCard";

export default function Home() {
  return (
    <main>
      <h1>재능나눔 부스 예약</h1>

      <div className="booth-list">
        {booths.map((booth) => (
          <BoothCard key={booth.id} booth={booth} />
        ))}
      </div>
    </main>
  );
}